**What it supports**

- Functions with `int` parameters (up to 6), `int` return values, and recursion
- Local variables with block scope, `if`/`else`, `while`, `return`, and calls
- Operators `+ - * / % < > <= >= == != && || !` and unary `-`, with C precedence and short-circuit `&&`/`||`
- Output is x86-64 AT&T assembly following the System V ABI, assembled and linked with `cc`

**Pipeline:** lexer → recursive-descent parser → AST → three-address IR with virtual registers → liveness intervals (extended across loops) → linear-scan register allocation over callee-saved registers, with spilling to the stack → assembly emission.

Save as `minicc.py` and run `python3 minicc.py prog.c`.

```python
#!/usr/bin/env python3
"""minicc: a small C-subset compiler targeting x86-64 (AT&T syntax, SysV ABI)."""
import re, os, sys, subprocess

DARWIN  = sys.platform == "darwin"
ARGREGS = ["%rdi", "%rsi", "%rdx", "%rcx", "%r8", "%r9"]
ALLOC   = ["%rbx", "%r12", "%r13", "%r14", "%r15"]   # callee-saved => allocatable
# %rax, %rcx, %rdx are scratch (rcx/rdx also serve as arg regs and for idiv)
PREC  = {"||": 1, "&&": 2, "==": 3, "!=": 3, "<": 4, ">": 4, "<=": 4, ">=": 4,
         "+": 5, "-": 5, "*": 6, "/": 6, "%": 6}
CC    = {"<": "l", ">": "g", "<=": "le", ">=": "ge", "==": "e", "!=": "ne"}
ARITH = {"+": "addq %rcx, %rax", "-": "subq %rcx, %rax", "*": "imulq %rcx, %rax"}

def SYM(name): return ("_" + name) if DARWIN else name

# ---------------------------------------------------------------- lexer
TOKEN_RE = re.compile(r"\s+|//[^\n]*|/\*.*?\*/|\d+|[A-Za-z_]\w*|==|!=|<=|>=|&&|\|\||[-+*/%<>=!(){};,]", re.S)

def lex(src):
    toks, i = [], 0
    while i < len(src):
        m = TOKEN_RE.match(src, i)
        if not m: raise SyntaxError(f"bad character {src[i]!r} at offset {i}")
        i, t = m.end(), m.group()
        if not (t.isspace() or t.startswith("//") or t.startswith("/*")):
            toks.append(t)
    return toks

# ---------------------------------------------------------------- parser
class Parser:
    def __init__(self, toks): self.t, self.p = toks, 0
    def peek(self, k=0):
        i = self.p + k
        return self.t[i] if i < len(self.t) else None
    def eat(self, want=None):
        t = self.peek()
        if t is None or (want is not None and t != want):
            raise SyntaxError(f"expected {want!r}, got {t!r}")
        self.p += 1
        return t
    @staticmethod
    def is_ident(t): return t is not None and (t[0].isalpha() or t[0] == "_")

    def program(self):
        funcs = []
        while self.peek() is not None: funcs.append(self.func())
        return funcs

    def func(self):
        self.eat("int"); name = self.eat(); self.eat("(")
        params = []
        if self.peek() != ")":
            while True:
                self.eat("int"); params.append(self.eat())
                if self.peek() != ",": break
                self.eat(",")
        self.eat(")")
        return name, params, self.block()

    def block(self):
        self.eat("{"); stmts = []
        while self.peek() != "}": stmts.append(self.stmt())
        self.eat("}")
        return ("block", stmts)

    def stmt(self):
        t = self.peek()
        if t == "int":
            self.eat(); name = self.eat(); init = None
            if self.peek() == "=": self.eat(); init = self.expr()
            self.eat(";"); return ("decl", name, init)
        if t == "if":
            self.eat("if"); self.eat("("); c = self.expr(); self.eat(")")
            th = self.stmt(); el = None
            if self.peek() == "else": self.eat("else"); el = self.stmt()
            return ("if", c, th, el)
        if t == "while":
            self.eat("while"); self.eat("("); c = self.expr(); self.eat(")")
            return ("while", c, self.stmt())
        if t == "return":
            self.eat(); e = self.expr(); self.eat(";"); return ("return", e)
        if t == "{": return self.block()
        if self.is_ident(t) and self.peek(1) == "=":
            name = self.eat(); self.eat("="); e = self.expr(); self.eat(";")
            return ("assign", name, e)
        e = self.expr(); self.eat(";")
        return ("expr", e)

    def expr(self, minp=1):
        lhs = self.unary()
        while True:
            op = self.peek()
            if op not in PREC or PREC[op] < minp: break
            self.eat(); rhs = self.expr(PREC[op] + 1)
            lhs = ("bin", op, lhs, rhs)
        return lhs

    def unary(self):
        t = self.peek()
        if t in ("-", "!"):
            self.eat(); return ("un", t, self.unary())
        return self.primary()

    def primary(self):
        t = self.peek()
        if t is None: raise SyntaxError("unexpected end of input")
        if t == "(":
            self.eat("("); e = self.expr(); self.eat(")"); return e
        self.eat()
        if t[0].isdigit(): return ("num", int(t))
        if self.is_ident(t):
            if self.peek() == "(":
                self.eat("("); args = []
                if self.peek() != ")":
                    args.append(self.expr())
                    while self.peek() == ",":
                        self.eat(","); args.append(self.expr())
                self.eat(")")
                return ("call", t, args)
            return ("var", t)
        raise SyntaxError(f"unexpected token {t!r}")

# ---------------------------------------------------------------- IR generation
# IR instructions are tuples; operands are virtual register ids (ints) or labels:
#   ("const", d, imm)  ("arg", d, i)  ("mov", d, s)  ("neg"|"not", d, a)
#   ("bin", op, d, a, b)  ("call", d, name, [args])  ("jz", a, L)  ("jmp", L)
#   ("label", L)  ("ret", a)
class IRGen:
    def __init__(self): self.code, self.nv, self.nl, self.scopes = [], 0, 0, []
    def temp(self):  self.nv += 1; return self.nv
    def label(self): self.nl += 1; return f"L{self.nl}"
    def emit(self, *ins): self.code.append(ins)
    def lookup(self, name):
        for sc in reversed(self.scopes):
            if name in sc: return sc[name]
        raise NameError(f"undefined variable '{name}'")

    def function(self, params, body):
        if len(params) > 6: raise NotImplementedError("at most 6 parameters")
        self.scopes = [{}]
        for i, p in enumerate(params):
            v = self.temp(); self.scopes[-1][p] = v; self.emit("arg", v, i)
        self.stmt(body)
        z = self.temp(); self.emit("const", z, 0); self.emit("ret", z)
        return self.code

    def stmt(self, n):
        k = n[0]
        if k == "block":
            self.scopes.append({})
            for x in n[1]: self.stmt(x)
            self.scopes.pop()
        elif k == "decl":
            init = self.expr(n[2]) if n[2] is not None else None
            v = self.temp()
            if init is None: self.emit("const", v, 0)
            else:            self.emit("mov", v, init)
            self.scopes[-1][n[1]] = v
        elif k == "assign":
            self.emit("mov", self.lookup(n[1]), self.expr(n[2]))
        elif k == "if":
            Lelse, Lend = self.label(), self.label()
            self.emit("jz", self.expr(n[1]), Lelse)
            self.stmt(n[2])
            if n[3] is not None:
                self.emit("jmp", Lend)
                self.emit("label", Lelse); self.stmt(n[3]); self.emit("label", Lend)
            else:
                self.emit("label", Lelse)
        elif k == "while":
            Ltop, Lend = self.label(), self.label()
            self.emit("label", Ltop)
            self.emit("jz", self.expr(n[1]), Lend)
            self.stmt(n[2])
            self.emit("jmp", Ltop); self.emit("label", Lend)
        elif k == "return":
            self.emit("ret", self.expr(n[1]))
        elif k == "expr":
            self.expr(n[1])
        else:
            raise ValueError(k)

    def expr(self, n):
        k = n[0]
        if k == "num":
            t = self.temp(); self.emit("const", t, n[1]); return t
        if k == "var":
            return self.lookup(n[1])
        if k == "call":
            args = [self.expr(a) for a in n[2]]
            if len(args) > 6: raise NotImplementedError("at most 6 arguments")
            t = self.temp(); self.emit("call", t, n[1], args); return t
        if k == "un":
            a = self.expr(n[2]); t = self.temp()
            self.emit("neg" if n[1] == "-" else "not", t, a)
            return t
        op = n[1]
        if op == "&&":   # short-circuit
            t = self.temp(); Lf, Lend = self.label(), self.label()
            self.emit("const", t, 1)
            self.emit("jz", self.expr(n[2]), Lf)
            self.emit("jz", self.expr(n[3]), Lf)
            self.emit("jmp", Lend)
            self.emit("label", Lf); self.emit("const", t, 0); self.emit("label", Lend)
            return t
        if op == "||":   # short-circuit
            t = self.temp(); Lb, Lend = self.label(), self.label()
            self.emit("const", t, 0)
            self.emit("jz", self.expr(n[2]), Lb)
            self.emit("const", t, 1); self.emit("jmp", Lend)
            self.emit("label", Lb)
            self.emit("jz", self.expr(n[3]), Lend)
            self.emit("const", t, 1); self.emit("label", Lend)
            return t
        a = self.expr(n[2]); b = self.expr(n[3]); t = self.temp()
        self.emit("bin", op, t, a, b)
        return t

# ---------------------------------------------------------------- liveness
def uses_defs(ins):
    op = ins[0]
    if op in ("label", "jmp"):          return [], []
    if op in ("jz", "ret"):             return [ins[1]], []
    if op in ("const", "arg"):          return [], [ins[1]]
    if op in ("mov", "neg", "not"):     return [ins[2]], [ins[1]]
    if op == "bin":                     return [ins[3], ins[4]], [ins[2]]
    if op == "call":                    return list(ins[3]), [ins[1]]
    raise ValueError(op)

def live_intervals(code):
    """Conservative [start, end] interval per vreg in linear order. Any interval
    overlapping a loop (a backward jump) is widened to cover the whole loop."""
    iv = {}
    for i, ins in enumerate(code):
        u, d = uses_defs(ins)
        for v in u + d:
            s, e = iv.get(v, (i, i))
            iv[v] = (min(s, i), max(e, i))
    labelpos = {ins[1]: i for i, ins in enumerate(code) if ins[0] == "label"}
    loops = []
    for j, ins in enumerate(code):
        if ins[0] in ("jmp", "jz"):
            t = labelpos[ins[-1]]
            if t <= j: loops.append((t, j))
    changed = True
    while changed:
        changed = False
        for t, j in loops:
            for v, (s, e) in list(iv.items()):
                if s <= j and e >= t:
                    ns, ne = min(s, t), max(e, j)
                    if (ns, ne) != (s, e):
                        iv[v] = (ns, ne); changed = True
    return iv

# ---------------------------------------------------------------- linear-scan allocation
def allocate(iv):
    loc, free, active, nspill = {}, list(ALLOC), [], 0
    def new_slot():
        nonlocal nspill
        slot = f"{-48 - 8 * nspill}(%rbp)"   # below the 5 callee-saved save slots
        nspill += 1
        return slot
    for v in sorted(iv, key=lambda v: iv[v][0]):
        s, e = iv[v]
        keep = []
        for a in active:                       # expire intervals that ended
            if a[0] < s: free.append(a[2])
            else:        keep.append(a)
        active = keep
        if free:
            r = free.pop(0); loc[v] = r; active.append((e, v, r))
        else:                                  # spill whichever ends last
            far = max(active, key=lambda a: a[0])
            if far[0] > e:
                active.remove(far)
                loc[far[1]] = new_slot()
                loc[v] = far[2]; active.append((e, v, far[2]))
            else:
                loc[v] = new_slot()
    return loc, nspill

# ---------------------------------------------------------------- code generation
def codegen_function(name, params, body):
    code = IRGen().function(params, body)
    iv = live_intervals(code)
    loc, nspill = allocate(iv)
    fs = (40 + 8 * nspill + 15) // 16 * 16      # keeps rsp 16-byte aligned
    ep = f".Lret_{name}"
    lab = lambda L: f".L{name}_{L}"

    out = [f"{SYM(name)}:", "pushq %rbp", "movq %rsp, %rbp", f"subq ${fs}, %rsp"]
    out += [f"movq {r}, {-8 * (i + 1)}(%rbp)" for i, r in enumerate(ALLOC)]

    for ins in code:
        op = ins[0]
        if op == "label":
            out.append(f"{lab(ins[1])}:")
        elif op == "jmp":
            out.append(f"jmp {lab(ins[1])}")
        elif op == "jz":
            out += [f"movq {loc[ins[1]]}, %rax", "testq %rax, %rax", f"je {lab(ins[2])}"]
        elif op == "const":
            out += [f"movabsq ${ins[2]}, %rax", f"movq %rax, {loc[ins[1]]}"]
        elif op == "arg":
            out.append(f"movq {ARGREGS[ins[2]]}, {loc[ins[1]]}")
        elif op == "mov":
            out += [f"movq {loc[ins[2]]}, %rax", f"movq %rax, {loc[ins[1]]}"]
        elif op in ("neg", "not"):
            out.append(f"movq {loc[ins[2]]}, %rax")
            if op == "neg": out.append("negq %rax")
            else:           out += ["cmpq $0, %rax", "sete %al", "movzbl %al, %eax"]
            out.append(f"movq %rax, {loc[ins[1]]}")
        elif op == "ret":
            out += [f"movq {loc[ins[1]]}, %rax", f"jmp {ep}"]
        elif op == "bin":
            bop, d, a, b = ins[1], ins[2], ins[3], ins[4]
            out += [f"movq {loc[a]}, %rax", f"movq {loc[b]}, %rcx"]
            if bop in ARITH:
                out.append(ARITH[bop])
            elif bop in ("/", "%"):
                out += ["cqto", "idivq %rcx"]
                if bop == "%": out.append("movq %rdx, %rax")
            else:
                out += ["cmpq %rcx, %rax", f"set{CC[bop]} %al", "movzbl %al, %eax"]
            out.append(f"movq %rax, {loc[d]}")
        elif op == "call":
            d, fn, args = ins[1], ins[2], ins[3]
            out += [f"movq {loc[a]}, {ARGREGS[i]}" for i, a in enumerate(args)]
            out += ["xorl %eax, %eax", f"call {SYM(fn)}", f"movq %rax, {loc[d]}"]
        else:
            raise ValueError(op)

    out.append(f"{ep}:")
    out += [f"movq {-8 * (i + 1)}(%rbp), {r}" for i, r in enumerate(ALLOC)]
    out += ["leave", "ret"]
    return out

# ---------------------------------------------------------------- driver
def main(argv):
    if len(argv) != 2: sys.exit("usage: minicc.py file.c")
    src = open(argv[1]).read()
    funcs = Parser(lex(src)).program()
    asm = [".text"]
    for name, params, body in funcs:
        asm.append(f".globl {SYM(name)}")
        asm += codegen_function(name, params, body)
    base = os.path.splitext(argv[1])[0]
    with open(base + ".s", "w") as f:
        f.write("\n".join(asm) + "\n")
    cmd = ["cc"] + (["-arch", "x86_64"] if DARWIN else []) + [base + ".s", "-o", base]
    subprocess.run(cmd, check=True)

if __name__ == "__main__":
    main(sys.argv)
```

