int fib(int n) { if (n < 2) return n; return fib(n - 1) + fib(n - 2); }

int gcd(int a, int b) { while (b != 0) { int t = a % b; a = b; b = t; } return a; }

int is_prime(int n) {
    if (n < 2) return 0;
    for (int i = 2; i * i <= n; i++) if (n % i == 0) return 0;
    return 1;
}

/* 12 simultaneously-live values > 10 allocatable registers => forces spills */
int pressure(int x) {
    int a = x+1, b = x+2, c = x+3, d = x+4, e = x+5, f = x+6,
        g = x+7, h = x+8, i = x+9, j = x+10, k = x+11, l = x+12;
    return a*b + c*d + e*f + g*h + i*j + k*l + a + l;
}

/* params arrive in rdi..r9 but get allocated elsewhere => parallel-move path */
int sum6(int a, int b, int c, int d, int e, int f) {
    return a + 2*b + 3*c + 4*d + 5*e + 6*f;
}

