    printf("gcd(1071, 462) = %ld\n", gcd(1071, 462));
    int count = 0;                       /* live across calls => callee-saved reg */
    for (int n = 0; n < 100; n++) count += is_prime(n);
    printf("primes below 100: %ld\n", count);
    printf("pressure(1) = %ld\n", pressure(1));
