             shape=box, style="filled,rounded", fillcolor="#F39C12",
             fontcolor=white, color="#9C640C", fontsize=12];

        edge [style=solid, color="#9C640C", label=""];
        s1 -> avg; s2 -> avg; s3 -> avg; s4 -> avg; s5 -> avg;
    }

    grid -> f1 [lhead=cluster_cv, label=" split training set\n into 5 folds"];

    // loop back for next candidate
    avg -> grid [label=" next θᵢ₊₁", style=dashed, color="#1ABC9C",
                 fontcolor="#117A65", constraint=false];

    // ---------- 4. Selection & final evaluation ----------
    best  [label="Select Best Hyperparameters\nθ* = argmax Mean CV Score",
           shape=hexagon, style=filled, fillcolor="#27AE60", fontcolor=white, color="#1E8449"];
    refit [label="Refit Model with θ*\non the FULL Training Set",
           fillcolor="#2ECC71", fontcolor=white, color="#1E8449"];
    final [label="Final Evaluation\non Held-out Test Set",
           shape=doubleoctagon, style=filled, fillcolor="#C0392B", fontcolor=white, color="#7B241C"];
    report [label="Unbiased Estimate of\nGeneralisation Performance",
            shape=note, style=filled, fillcolor="#FDEBD0", color="#B9770E"];

    avg   -> best  [label=" after all m candidates"];
    best  -> refit;
    refit -> final;
    test  -> final [style=dashed, color="#E74C3C", label=" used once"];
    final -> report;

    // ---------- Legend ----------
    legend [shape=plain, label=<
      <TABLE BORDER="1" CELLBORDER="0" CELLSPACING="4" CELLPADDING="4" COLOR="#7F8C8D" BGCOLOR="white">
        <TR><TD COLSPAN="2"><B>Legend</B></TD></TR>
        <TR><TD BGCOLOR="#5DADE2" WIDTH="20"> </TD><TD ALIGN="LEFT">Training fold</TD></TR>
        <TR><TD BGCOLOR="#E67E22" WIDTH="20"> </TD><TD ALIGN="LEFT">Validation fold</TD></TR>
        <TR><TD BGCOLOR="#E74C3C" WIDTH="20"> </TD><TD ALIGN="LEFT">Test set (untouched)</TD></TR>
        <TR><TD BGCOLOR="#1ABC9C" WIDTH="20"> </TD><TD ALIGN="LEFT">Hyperparameter loop</TD></TR>
        <TR><TD BGCOLOR="#27AE60" WIDTH="20"> </TD><TD ALIGN="LEFT">Model selection / refit</TD></TR>
      </TABLE>>];
    { rank=same; data; legend; }
