          font-size: 0.85em;
          font-weight: 700;
          line-height: 1;
          user-select: none;
        }
        .icon::before { content: "+"; }
        :host([open]) .icon::before { content: "\\2212"; } /* minus sign */

        .intro  { margin-top: 0.75em; }

        .details { display: none; margin-top: 0.5em; }
        :host([open]) .details { display: block; }

        .more-btn {
