        <slot name="intro"></slot>
      </div>

      <div class="details" id="details" part="details">
        <slot name="details"></slot>
      </div>

      <button class="more-btn" part="more-button">expand more</button>
    `;

    this.#headerBtn = root.querySelector('.header-btn');
    this.#moreBtn   = root.querySelector('.more-btn');
    this.#detailsEl = root.querySelector('.details');

    this.#headerBtn.addEventListener('click', () => this.toggle());
    this.#moreBtn.addEventListener('click', () => {
      this.open = true;
      this.#headerBtn.focus(); // the button disappears, so move focus somewhere sensible
    });
  }

  get open() {
    return this.hasAttribute('open');
  }
  set open(value) {
    this.toggleAttribute('open', Boolean(value));
  }

  toggle() {
    this.open = !this.open;
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name !== 'open' || oldValue === newValue) return;
    const isOpen = this.open;
    this.#headerBtn.setAttribute('aria-expanded', String(isOpen));
    this.#detailsEl.setAttribute('aria-hidden', String(!isOpen));
    this.dispatchEvent(new CustomEvent('toggle', { detail: { open: isOpen }, bubbles: true }));
  }
}

