├── nginx.cue           # nginx container, proxy config, volumes
├── storage.cue         # namespace + PVC
├── workload.cue        # Deployment + Service
├── manifests.cue       # ordered list of everything to apply
└── commands_tool.cue   # `cue cmd dump` / `cue cmd apply`
