```
homelab/
├── cue.mod/
│   └── module.cue
├── schema.cue
├── app.cue
├── home.cue
└── cluster.cue
```

### `cue.mod/module.cue`

```cue
module: "example.com/homelab"
language: version: "v0.11.0"
```

### `schema.cue`

```cue
package homelab

// A single mount of a pod-level volume into a container.
#Mount: {
	volume:   string
	path:     string
	subPath?: string
	readOnly: bool | *false
}

// A container in the pod. Keyed by name in #App.containers.
#Container: {
	image:     string
	port:      int & >0 & <65536
	env: [string]: string
	mounts: [...#Mount]
	probePath: string | *"/"
	resources?: {
		requests?: [string]: string
		limits?: [string]: string
	}
}

// A pod-level volume, backed by a claim or a ConfigMap.
#Volume: {
	kind:   "pvc" | "configMap"
	source: string
}

// A PersistentVolumeClaim owned by the app.
#Claim: {
	size: string
}
```

### `app.cue`

```cue
package homelab

// #App turns a short description into the Kubernetes objects it needs:
// ConfigMaps, PVCs, one Deployment, and one Service.
#App: {
	// --- Inputs ----------------------------------------------------------
	appName:    string
	namespace:  string | *"home"
	replicas:   int | *1
	containers: [string]: #Container
	volumes:    [string]: #Volume
	claims:     [string]: #Claim
	configMaps: [string]: [string]: string
	service: {
		port:            int | *80
		targetContainer: string
	}

	// --- Shared metadata -------------------------------------------------
	_namespace: namespace
	_labels: {
		"app.kubernetes.io/name":       appName
		"app.kubernetes.io/managed-by": "cue"
	}
	_selector: {"app.kubernetes.io/name": appName}
	_meta: {name: appName, namespace: _namespace, labels: _labels}
	_targetPort: containers[service.targetContainer].port
	_replicas:   replicas

	// --- Pod building blocks ---------------------------------------------
	_containerSpecs: [
		for cname, c in containers {
			name:  cname
			image: c.image
			ports: [{containerPort: c.port}]
			env: [for k, v in c.env {name: k, value: v}]
			volumeMounts: [
				for m in c.mounts {
					name:      m.volume
					mountPath: m.path
					if m.subPath != _|_ {subPath: m.subPath}
					readOnly: m.readOnly
				}
			]
			readinessProbe: httpGet: {path: c.probePath, port: c.port}
			if c.resources != _|_ {resources: c.resources}
		}
	]

	_volumeSpecs: [
		for vname, v in volumes {
			name: vname
			if v.kind == "pvc" {persistentVolumeClaim: claimName: "\(appName)-\(v.source)"}
			if v.kind == "configMap" {configMap: name: "\(appName)-\(v.source)"}
		}
	]

	// --- Objects ---------------------------------------------------------
	_configMapSpecs: [
		for cmName, files in configMaps {
			apiVersion: "v1"
			kind:       "ConfigMap"
			metadata: {name: "\(appName)-\(cmName)", namespace: _namespace, labels: _labels}
			data: files
		}
	]

	_claimSpecs: [
		for cname, c in claims {
			apiVersion: "v1"
			kind:       "PersistentVolumeClaim"
			metadata: {name: "\(appName)-\(cname)", namespace: _namespace, labels: _labels}
			spec: {
				accessModes: ["ReadWriteOnce"]
				resources: requests: storage: c.size
			}
		}
	]

	_deployment: {
		apiVersion: "apps/v1"
		kind:       "Deployment"
		metadata:   _meta
		spec: {
			replicas: _replicas
			selector: matchLabels: _selector
			// Single-replica apps with ReadWriteOnce storage must not run two pods
			// at once, so replace the old pod before starting the new one.
			strategy: type: "Recreate"
			template: {
				metadata: labels: _labels
				spec: {
					containers: _containerSpecs
					volumes:    _volumeSpecs
				}
			}
		}
	}

	_service: {
		apiVersion: "v1"
		kind:       "Service"
		metadata:   _meta
		spec: {
			selector: _selector
			ports: [{name: "http", port: service.port, targetPort: _targetPort}]
		}
	}

	// Every object this app produces, in apply order.
	objects: [for group in [_configMapSpecs, _claimSpecs, [_deployment, _service]] for o in group {o}]
}
```

### `home.cue`

```cue
package homelab

// --- Reusable container definitions -----------------------------------

#HomeAssistant: #Container & {
	// Pin a version in production, e.g. "2025.1.4", instead of "stable".
	image: "ghcr.io/home-assistant/home-assistant:stable"
	port:  8123
	env: TZ: "Europe/London"
	mounts: [
		{volume: "config", path: "/config"},
		// Overlay a read-only configuration.yaml onto the persistent /config.
		{volume: "ha-config", path: "/config/configuration.yaml", subPath: "configuration.yaml", readOnly: true},
	]
	resources: requests: {cpu: "100m", memory: "512Mi"}
}

#Nginx: #Container & {
	image: "docker.io/library/nginx:1.27-alpine"
	port:  80
	mounts: [
		{volume: "nginx-conf", path: "/etc/nginx/conf.d", readOnly: true},
	]
	resources: requests: {cpu: "10m", memory: "16Mi"}
}

// --- Configuration files ----------------------------------------------

// Home Assistant must trust the proxy, or it rejects forwarded requests.
haConfiguration: """
    default_config:

    http:
      use_x_forwarded_for: true
      trusted_proxies:
        - 127.0.0.1
        - ::1
    """

// Reverse proxy to HA on localhost, with the headers WebSockets need.
nginxConf: """
    server {
        listen 80;
        client_max_body_size 50m;

        location / {
            proxy_pass http://127.0.0.1:8123;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection "upgrade";
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_read_timeout 86400;
        }
    }
    """

// --- The app ----------------------------------------------------------

apps: home: #App & {
	appName:   "home"
	namespace: "home"

	claims: config: size: "10Gi"

	volumes: {
		config:      {kind: "pvc", source: "config"}
		"ha-config": {kind: "configMap", source: "ha-config"}
		"nginx-conf": {kind: "configMap", source: "nginx-conf"}
	}

	configMaps: {
		"ha-config": {"configuration.yaml": haConfiguration}
		"nginx-conf": {"default.conf": nginxConf}
	}

	containers: {
		"home-assistant": #HomeAssistant
		nginx:            #Nginx
	}

	service: targetContainer: "nginx"
}
```

